326: # -Range (wave 24, T1): `git diff --shortstat <range> --` once, in the repository root - "the
327: # range changes N files, M lines" (M = insertions + deletions). { Range; Files; Insertions;
328: # Deletions; Lines; Error ('' or why the range is refused: not a revision range git knows here,
329: # an argument that could be read as an option, git not runnable) }.
330: function Get-RangeStat {
331:     param([string]$Root, [string]$Range)
332:     $r = [pscustomobject]@{ Range = $Range; Files = 0; Insertions = 0; Deletions = 0; Lines = 0; Error = '' }
333:     if (-not $Range -or $Range.StartsWith('-') -or $Range -match '[\s\x00-\x1f]') {
334:         $r.Error = "-Range '$Range' is not a git revision range (e.g. a1b2c3d..HEAD; no spaces, not starting with '-')"
335:         return $r
336:     }
337:     $cap = Invoke-GitCapture -Root $Root -GitArgs @('diff', '--shortstat', $Range, '--')
338:     if ($null -eq $cap) { $r.Error = "-Range '$Range': git could not be started in $Root"; return $r }
339:     if ($cap.ExitCode -ne 0) {
340:         $why = @(([string]$cap.Err) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ }) | Select-Object -First 1
341:         $r.Error = "-Range '$Range' is not a revision range git knows in $Root (git diff --shortstat: $(if ($why) { $why } else { "exit $($cap.ExitCode)" }))"
342:         return $r
343:     }
344:     $out = $script:Utf8NoBom.GetString($cap.Bytes)
345:     if ($out -match '(\d+) files? changed') { $r.Files = [int]$Matches[1] }
346:     if ($out -match '(\d+) insertions?\(\+\)') { $r.Insertions = [int]$Matches[1] }
347:     if ($out -match '(\d+) deletions?\(-\)') { $r.Deletions = [int]$Matches[1] }
348:     $r.Lines = $r.Insertions + $r.Deletions
349:     return $r
350: }
