5220:         $fp = ''
5221:         if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
5222:         if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
5223:     }
5224:     # one group per label, then labels that share a fingerprint are merged (to a fixed point)
5225:     $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
5226:     for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
5227:     $changed = $true
5228:     while ($changed) {
5229:         $changed = $false
