5231:             for ($j = $i + 1; $j -lt $labels.Count; $j++) {
5232:                 $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
5233:                 if ($gi -eq $gj) { continue }
