5280:         $limit = 0
5281:         foreach ($l in $g.Labels) {
5282:             $v = 1
5283:             if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
5284:             if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
5285:         }
5286:         $effective += [Math]::Min($limit, $g.Positions.Count)
5287:         $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
5288:     }
5289:     foreach ($l in $eg.Labels) { $limits[$l] = $out[$eg.IndexOfLabel[$l]].Limit }
5290:     if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
5291:     $count = @($Runners | Where-Object { $_ }).Count
5292:     $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
