4263:         $out.Add('')
4264:         $sal = $turn.Salvage
4265:         $items = @($sal.Items | Where-Object { $_ })
4266:         if ($items.Count -eq 0) { $out.Add('_(no agent message or reasoning text in this turn''s event stream)_'); $out.Add('') }
4267:         $nMsg = 0; $nRea = 0
4268:         foreach ($it in $items) {
4269:             if ($it.Kind -eq 'reasoning') { $nRea++; $out.Add("**Reasoning $($nRea):**") } else { $nMsg++; $out.Add("**Agent message $($nMsg):**") }
4270:             $out.Add('')
