4274:         $tools = @($sal.Tools | Where-Object { $_ })
4275:         $out.Add("**Tool calls ($($tools.Count)):**$(if ($tools.Count -eq 0) { ' none' })")
4276:         if ($tools.Count -gt 0) { $out.Add(''); foreach ($tl in $tools) { $out.Add("- ``$(([string]$tl) -replace '`', "'")``") } }
4277:         $out.Add('')
