4282: # Classes of a provider failure, tried in this order (case-insensitive). permission comes
4283: # first (0.4.0, agy F11: a tool the headless print mode cannot grant was auto-denied and
4284: # the turn produced nothing). capability comes next: "Your token plan does not support
4285: # response_format" is a capability rejection, not a quota one. auth matches whole words
4286: # only ("text authored by" is not auth). transport stays last. Google's wordings (the agy
4287: # engine): RESOURCE_EXHAUSTED -> quota, UNAUTHENTICATED / PERMISSION_DENIED / "not signed
4288: # in" -> auth, INVALID_ARGUMENT / "invalid model selection" -> capability, UNAVAILABLE /
4289: # DEADLINE_EXCEEDED -> transport.
4290: # A usage limit said in WORDS ($script:QuotaTextPattern: usage limit, quota, rate limit, ...)
4291: # is quota even under an auth status, and is tried right before auth: Kimi Code answers "403
4292: # Forbidden: You've reached your 5-hour usage limit..." (live ledger, 2026-09-26), which the
4293: # 403 must not turn into an auth failure - the preflight would refuse that endpoint for 24 h.
4294: $script:QuotaTextPattern = '(?i)usage[ _]limit|quota|rate[ _]limit|resource_exhausted|too many requests'
4295: $script:FailureClassPatterns = [ordered]@{
4296:     'permission' = '(?i)no output produced|auto-denied|permission that headless mode'
4297:     'capability' = '(?i)not supported|unsupported|does(?: not|n[''\u2019]t) support|do not support|feature_not_supported|json_schema|invalid_argument|invalid model selection|conflicts with --effort'
4298:     'auth'       = '(?i)\b40[13]\b|unauthori[sz]ed|forbidden|invalid[ _]api[ _]key|\bauthentication\b|\bauth\b|\bapi key\b|permission_denied|unauthenticated|not signed in|login required|sign in to'
4299:     'quota'      = '(?i)usage[ _]limit|quota|rate[ _]limit|\b429\b|insufficient balance|too many requests|credits? exhausted|credit balance|payment required|\b402\b|token plan|plan exhausted|billing|resource_exhausted|rate_limit_exceeded'
4300:     'transport'  = '(?i)timeout|timed out|connection|econn|enotfound|\bdns\b|\btls\b|certificate|\b50[234]\b|network|\bunavailable\b|deadline_exceeded'
4301: }
4302: $script:BuiltinOpenAiFingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes('cc-provider-v1|builtin:openai'))
