4304: # permission | capability | auth | quota | transport | unknown
4305: function Get-ProviderFailureClass {
4306:     param([string]$Message)
4307:     foreach ($k in $script:FailureClassPatterns.Keys) {
4308:         if ($k -eq 'auth' -and $Message -match $script:QuotaTextPattern) { return 'quota' }
4309:         if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
4310:     }
4311:     return 'unknown'
4312: }
