4314: # The provider's own error inside a failure text: an SSE payload `data:{"error":{...}}`
4315: # (MiMo sends its rejections that way) or a bare `{"error":{...}}` -> error.message and
4316: # error.code; otherwise the text itself. { Code; Message }.
4317: function ConvertFrom-ProviderErrorText {
4318:     param([string]$Text)
4319:     $r = [pscustomobject]@{ Code = ''; Message = (ConvertTo-OneLine $Text) }
4320:     if (-not $Text) { return $r }
4321:     $candidates = New-Object System.Collections.Generic.List[string]
4322:     foreach ($m in [regex]::Matches($Text, '(?m)data:\s*(\{.*\})\s*$')) { $candidates.Add($m.Groups[1].Value) }
4323:     $at = $Text.IndexOf('{"error"')
4324:     if ($at -ge 0) { $candidates.Add($Text.Substring($at).Trim()) }
4325:     foreach ($json in $candidates) {
4326:         $o = $null
4327:         try { $o = ConvertFrom-Json -InputObject $json } catch { continue }
4328:         $e = Get-PropertyValue $o 'error' $null
4329:         if ($null -eq $e) { continue }
4330:         if ($e -is [string]) { $r.Message = ConvertTo-OneLine $e; return $r }
4331:         $msg = [string](Get-PropertyValue $e 'message' '')
4332:         if ($msg) { $r.Message = ConvertTo-OneLine $msg }
4333:         $r.Code = [string](Get-PropertyValue $e 'code' '')
4334:         if (-not $r.Code) { $r.Code = [string](Get-PropertyValue $e 'type' '') }
4335:         return $r
3630:         } else {
3631:             & $fail "empty reply$(if ($bestErr) { " - $(ConvertTo-OneLine $bestErr)" })" '' @($bestErr)
3632:         }
3633:         return $o
3634:     }
3635:     $o.Ok = $true
3636:     $o.Outcome = 'usable reply'
3637:     $w = New-Object System.Collections.Generic.List[string]
3638:     if ($denial) { $w.Add("denial notice: $(ConvertTo-OneLine $denial)") }
3639:     foreach ($wl in $warnLines) { $w.Add((ConvertTo-OneLine $wl)) }
3640:     $o.Warnings = [string[]]$w.ToArray()
3641:     return $o
3642: }
