3646: # The Muse sign-in (D5). With TBH_CREDENTIAL_BACKEND=file the CLI keeps it in
3647: # ~/.config/muse/auth.json (home: USERPROFILE on Windows, else HOME); any other backend is the OS
3648: # keychain, which the bridge cannot read (on Windows the keychain write fails anyway: the file
3649: # backend is required there). The file is read for the presence of providers.meta and its
3650: # `mechanism` value only (an enum such as oauth, never a secret); the parsed object is never
3651: # logged, returned or written, and a parse error is reported without its text. Cached per
3652: # backend and path for this process - for listings and the preflight; -Fresh (wave 24, F15-1)
3653: # reads the file again (and refreshes the cache): the launch guard right before every
3654: # Start-Process of a muse turn uses it. { Backend (file | keychain); State (ok | missing |
3655: # unknown); Reason; Cause (wave 23b: the reason without its remedy, '' when ok - the billing
3656: # guard names it); Mechanism ('' when not read; 'unrecognized' for a value that is not a short
3657: # identifier - never shown) }.
3658: $script:MuseCredentialCache = @{}
3659: $script:MuseAuthShown = '~/.config/muse/auth.json'
3660: function Get-MuseAuthPath {
3661:     $h = ''
3662:     if ($script:OnWindows) { $h = [string]$env:USERPROFILE }
3663:     if (-not $h) { $h = [string]$env:HOME }
3664:     if (-not $h) { $h = [string]$HOME }
3665:     if (-not $h) { return '' }
3666:     return (Join-Path (Join-Path (Join-Path $h '.config') 'muse') 'auth.json')
3667: }
3668: function Get-MuseCredentialInfo {
3669:     param([switch]$Fresh)
3670:     $backend = ([string]$env:TBH_CREDENTIAL_BACKEND).Trim().ToLowerInvariant()
3671:     $path = Get-MuseAuthPath
3672:     $key = "$backend|$path"
3673:     if (-not $Fresh -and $script:MuseCredentialCache.ContainsKey($key)) { return $script:MuseCredentialCache[$key] }
3674:     $info = [pscustomobject]@{ Backend = $(if ($backend -eq 'file') { 'file' } else { 'keychain' }); State = 'unknown'; Reason = ''; Cause = ''; Mechanism = '' }
3675:     $shown = $script:MuseAuthShown
3676:     if ($backend -ne 'file') {
3677:         $info.Cause = "TBH_CREDENTIAL_BACKEND is $(if ($backend) { "'$backend'" } else { 'not set' }): the keychain backend cannot be read"
3678:         $info.Reason = "sign-in not checkable: TBH_CREDENTIAL_BACKEND is $(if ($backend) { "'$backend'" } else { 'not set' }) (the keychain backend cannot be read; set TBH_CREDENTIAL_BACKEND=file - required on Windows - and run ``muse login``)"
3679:     } elseif (-not $path) {
3680:         $info.Cause = 'no home directory (USERPROFILE / HOME)'
3681:         $info.Reason = 'sign-in not checkable: no home directory (USERPROFILE / HOME)'
3682:     } elseif (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
3683:         $info.State = 'missing'
3684:         $info.Cause = "$shown does not exist"
3685:         $info.Reason = "not signed in: $shown does not exist (run ``muse login`` with TBH_CREDENTIAL_BACKEND=file)"
3686:     } else {
3687:         $data = $null
3688:         $why = ''
3689:         $text = Read-SharedText -Path $path
3690:         if (-not $text -or -not $text.Trim()) { $why = 'is empty or could not be read' }
3691:         else {
3692:             try { $data = ConvertFrom-Json -InputObject $text } catch { $why = 'does not parse as JSON' }
3693:             if (-not $why -and -not (Test-IsJsonObject $data)) { $why = 'is not a JSON object' }
3694:         }
3695:         $text = $null
3696:         if ($why) {
3697:             $info.Cause = "$shown $why"
3698:             $info.Reason = "sign-in not checkable: $shown $why"
3699:         } else {
3700:             $providers = Get-PropertyValue $data 'providers' $null
3701:             $meta = $null
3702:             if (Test-IsJsonObject $providers) { $meta = Get-PropertyValue $providers 'meta' $null }
3703:             if (-not (Test-IsJsonObject $meta)) {
3704:                 $info.State = 'missing'
3705:                 $info.Cause = "$shown has no Meta sign-in (providers.meta)"
3706:                 $info.Reason = "not signed in: $shown has no Meta sign-in (providers.meta; run ``muse login``)"
3707:             } else {
3708:                 $mech = Get-PropertyValue $meta 'mechanism' $null
3709:                 if (-not ($mech -is [string]) -or -not $mech.Trim()) {
3710:                     $info.Cause = "providers.meta in $shown names no mechanism"
3711:                     $info.Reason = "sign-in not checkable: providers.meta in $shown names no mechanism"
3712:                 } else {
3713:                     $info.State = 'ok'
3714:                     if ($mech -cmatch '^[A-Za-z][A-Za-z0-9_.-]{0,31}$') { $info.Mechanism = $mech } else { $info.Mechanism = 'unrecognized' }
3715:                     $info.Reason = "signed in ($shown`: providers.meta, mechanism $($info.Mechanism))"
3716:                 }
3717:             }
3718:         }
3719:         $data = $null
3720:     }
3721:     $script:MuseCredentialCache[$key] = $info
3722:     return $info
3723: }
