3726: # started): ok (providers.meta with a mechanism), missing (no file, no providers.meta), unknown
3727: # (the keychain backend, a file that does not parse, no mechanism). Since wave 23b (F09-1)
3728: # missing and unknown refuse the LAUNCH itself (Get-MuseLaunchBlock: no oauth sign-in is
3729: # established) - with -SkipPreflight too, before this check is ever consulted.
3730: function Get-MuseSignIn {
3731:     param([string]$Launcher = '', [int]$TimeoutSec = 0)
3732:     $c = Get-MuseCredentialInfo
3733:     return (New-CredentialResult $c.State $c.Reason)
